 bool PauseInput(){var k=Keyboard.current;if(pauseOpen){if(k!=null){if(pausePage==1&&choosingEquipment){if(k.escapeKey.wasPressedThisFrame){choosingEquipment=false;return true;}var choices=EquipmentChoices();int deltaChoice=k.downArrowKey.wasPressedThisFrame?1:k.upArrowKey.wasPressedThisFrame?-1:0;equipmentChoice=(equipmentChoice+deltaChoice+choices.Count)%choices.Count;if(k.enterKey.wasPressedThisFrame||k.numpadEnterKey.wasPressedThisFrame)ConfirmEquipmentChoice();return true;}if(k.escapeKey.wasPressedThisFrame){if(pausePage==0)SetPause(false);else pausePage=0;return true;}if(pausePage==3)PauseMapKeys(k);int count=pausePage==0?PauseMainOptions().Length:pausePage==1?3:pausePage==2?18:0;int delta=k.rightArrowKey.wasPressedThisFrame?1:k.leftArrowKey.wasPressedThisFrame?-1:k.downArrowKey.wasPressedThisFrame?(pausePage==2?6:1):k.upArrowKey.wasPressedThisFrame?(pausePage==2?-6:-1):0;if(count>0&&delta!=0){if(pausePage==0)pauseSelection=(pauseSelection+delta+count)%count;else pauseRow=(pauseRow+delta+count)%count;}if(k.enterKey.wasPressedThisFrame||k.numpadEnterKey.wasPressedThisFrame){if(pausePage==0)OpenPausePage(pauseSelection);else if(pausePage==1&&count>0)OpenEquipmentChoice();else if(pausePage==2&&count>0)UseOutsidePotion(pauseRow);}}return true;}if(!battle&&!IntroductionActive&&!lost&&!levelComplete&&k!=null&&(k.enterKey.wasPressedThisFrame||k.numpadEnterKey.wasPressedThisFrame)){SetPause(true);return true;}return false;}
