 void UseOutsidePotion(int index){var cells=InventoryCells();if(index<0||index>=cells.Count){pauseNotice="Casilla vacía.";return;}var cell=cells[index];if(cell.equipment>=0){EquipItem(Character.equipment[cell.equipment].id);return;}int i=cell.potion;var item=inventorySettings.items[i];if(item.unavailable){pauseNotice="Función todavía no disponible.";return;}if(item.gainOneLevel){UseLevelUpCheat(i);return;}if(item.returnToSavePoint){UseFastBackward(i);return;}if(item.keyItem){pauseNotice="Llave: se usa automáticamente en su puerta.";return;}if(hp>=MaximumHP){pauseNotice="La vida ya está completa.";return;}int healed=Mathf.Min(Mathf.Max(0,item.healHP),MaximumHP-hp);if(healed==0)return;hp+=healed;itemCounts[i]--;NotifyHealing(item,healed);pauseNotice="Recuperas "+healed+" HP.";}
 void DrawPause(){float scale=Mathf.Min(Screen.width/1280f,Screen.height/720f);GUI.matrix=Matrix4x4.Scale(new Vector3(scale,scale,1));float w=Screen.width/scale,h=Screen.height/scale;GUI.depth=-100;GUI.enabled=true;GUI.color=new Color(0,0,0,.8f);GUI.DrawTexture(new Rect(0,0,w,h),Texture2D.whiteTexture);GUI.color=Color.white;NeonDungeonUI.FontSize=Layout.textFontSize;GUI.skin.button.fontSize=22;GUI.contentColor=new Color(.65f,.85f,1);GUI.backgroundColor=new Color(.12f,.05f,.3f);if(saveSlotsOpen){DrawSaveSlots(w,h);return;}if(startMenuOpen){DrawStartupMenu(w,h);return;}if(pausePage==1){DrawCharacterCard(w,h);return;}if(pausePage==2){DrawInventoryGrid(w,h);DrawCheatPulse(w,h);return;}float x=w/2-480,y=h/2-290;NeonDungeonUI.Message(new Rect(x,y,960,80),"PAUSA / "+new[]{"MENÚ","PERSONAJE","INVENTARIO","MAPA","AJUSTES"}[pausePage]);
