 if(pausePage==3)DrawPauseMap(w,y);
 if(pausePage==4){var crt=view!=null?view.GetComponent<HelmetCRTController>():null;bool on=PlayerPrefs.GetInt(HelmetCRTController.PreferenceKey,1)!=0;bool selected=GUI.Toggle(new Rect(w/2-170,y+180,340,40),on,"Pantalla CRT del casco");if(selected!=on&&crt!=null)crt.SetUserEnabled(selected);NeonDungeonUI.Label(new Rect(w/2-220,y+235,440,60),"El HUD y los menús permanecen sin distorsión.",true);}
 if(pausePage!=3)NeonDungeonUI.Label(new Rect(x+35,y+580,890,28),"Flechas: elegir / ENTER: confirmar / ESC: volver",true);
 if(pausePage!=0&&GUI.Button(new Rect(w/2-100,y+535,200,40),"VOLVER"))pausePage=0;GUI.color=Color.white;}
